import type { StatsChartRow, StatsDataset } from '../../services/stats/project_stats_types';

const CSV_COLUMNS = [
    'dataset',
    'chart_role',
    'available',
    'grouping',
    'utc_bucket_start',
    'utc_bucket_end',
    'identity',
