    'failed_count',
    'cancelled_count',
    'aggregation',
    'deviation',
];

function csvValue(value: boolean | number | string) {
    const text = String(value);

    return /[",\r\n]/u.test(text) ? `"${text.replaceAll('"', '""')}"` : text;
}

export function serializeStatsCsv(dataset: StatsDataset, rows: StatsChartRow[]) {
    const records = rows.map((row) => [
        dataset,
        row.chartRole,
        row.available,
        row.grouping,
        row.utcBucketStart ?? '',
        row.utcBucketEnd ?? '',
        row.identity,
        row.provider ?? '',
        row.limitId ?? '',
        row.windowId ?? '',
        row.agent ?? '',
        row.actionType ?? '',
        row.actionId ?? '',
        row.seriesIdentity ?? '',
        row.seriesLabel ?? '',
        row.stackIdentity ?? '',
        row.displayLabel,
        row.metric,
        row.unit,
        row.value,
        row.numerator ?? '',
        row.denominator ?? '',
        row.sampleCount ?? '',
        row.statusCounts?.completed ?? '',
        row.statusCounts?.failed ?? '',
        row.statusCounts?.cancelled ?? '',
        row.aggregation ?? '',
        row.deviation ?? '',
    ]);

    return `${[CSV_COLUMNS, ...records].map((record) => record.map(csvValue).join(',')).join('\r\n')}\r\n`;
}

/** Downloads generated stats CSV without writing repository files. */
export function downloadStatsCsv(dataset: StatsDataset, rows: StatsChartRow[]) {
    const blob = new Blob([serializeStatsCsv(dataset, rows)], { type: 'text/csv;charset=utf-8' });
    const url = URL.createObjectURL(blob);
    const anchor = document.createElement('a');
    anchor.download = `md2-stats-${dataset}.csv`;
    anchor.href = url;
    anchor.click();
    URL.revokeObjectURL(url);
}

function padDurationPart(value: number) {
    return value.toString().padStart(2, '0')
}

/** Formats an elapsed millisecond span as `m:ss`, or `h:mm:ss` past an hour. */
export function formatDuration(ms: number) {
    const totalSeconds = Math.max(0, Math.floor(ms / 1000))
    const seconds = totalSeconds % 60
    const minutes = Math.floor(totalSeconds / 60) % 60
    const hours = Math.floor(totalSeconds / 3600)

    if (hours > 0) return `${hours}:${padDurationPart(minutes)}:${padDurationPart(seconds)}`

    return `${minutes}:${padDurationPart(seconds)}`
}
